//! CLI binary `rho-dlog`.
//!
//! Usage: `rho-dlog --curve <NAME> --p <x,y> --q <x,y>`
//!
//! Solves the ECDLP `Q = k·P` on one of the built-in curves and prints `k`.
//!
//! # Supported curves
//!
//! - `secp-toy` — downsized GLV-friendly secp256k1-style curve (63-bit order).
//! - `generic`  — Weierstrass curve `y² = x³ − 3x + 1` over a 63-bit prime, with a subgroup of
//!   prime order 561_103 (20 bits, about 2¹⁹) generated by its default base point. Runnable
//!   demonstrations finish in a fraction of a second.
//!
//! # Point format
//!
//! Pass each point as `x,y` with no spaces (decimal integers):
//!
//! ```text
//! rho-dlog --curve secp-toy --p 2,3236101131256320111 --q 922337203685479039,132612412593110192
//! ```
//!
//! On `generic` the base point and target must lie in the order-561_103 subgroup; points outside
//! it are reported as invalid input, never projected onto it. For example, with the default
//! base point `G`, the target `Q = 424242·G` solves to `k = 424242`:
//!
//! ```text
//! rho-dlog --curve generic --q 1000932015531192845,9048581680910854061
//! ```
//!
//! Output: `k = <decimal>` followed by a verification line.
//!
//! # Parallel mode
//!
//! Pass `--walkers N` (N ≥ 1) to use the distinguished-point parallel solver
//! ([`rho::ecdlp::solve_dp`]) instead of the single-threaded Brent solver.
//! `--theta T` controls the DP threshold (default: 10).  `--max-steps S` caps the total walk
//! steps across all walkers (default: derived from the group order, walkers and threshold).
//!
//! # GLV mode
//!
//! Pass `--glv` to enable the GLV endomorphism solver (`solve_dp_glv`).
//! Requires `--walkers > 0` and `--curve secp-toy` (any other curve is reported as
//! unsupported by the solver).  The GLV endomorphism
//! collapses the 6-orbit `{W, φ(W), φ²(W), −W, −φ(W), −φ²(W)}` to a single
//! canonical representative, which is expected (heuristic, not measured) to give about a √3
//! speedup vs the negation-map-only walk.

use clap::Parser;
use crypto_bigint::Uint;
use rho::curve::AffinePoint;
use rho::curve::generic::{generic_curve, N as GENERIC_N};
use rho::curve::secp_k1_toy::{secp_k1_toy, N as SECP_N};
use rho::ecdlp::{
    solve_brent, solve_dp, solve_dp_batch, solve_dp_glv, solve_dp_negmap, DlogError, InputDefect,
};
use shared_field::{Fp, FpMonty4 as FpMonty};

#[derive(Parser, Debug)]
#[command(name = "rho-dlog", about = "Pollard rho ECDLP solver")]
struct Args {
    /// Curve name: `secp-toy` or `generic`.
    #[arg(long, default_value = "secp-toy")]
    curve: String,

    /// Base point P as `x,y` (decimal, no spaces).  Defaults to the curve generator.
    #[arg(long)]
    p: Option<String>,

    /// Target point Q as `x,y` (decimal, no spaces).  Required.
    #[arg(long)]
    q: String,

    /// RNG seed for reproducibility (default: 0).
    #[arg(long, default_value_t = 0u64)]
    seed: u64,

    /// Maximum retry attempts on degenerate failures (default: 20).
    /// Only used by the single-threaded Brent solver.
    #[arg(long, default_value_t = 20usize)]
    retries: usize,

    /// Number of parallel walker threads for the DP solver (default: 0 = use Brent).
    ///
    /// When > 0, the distinguished-point parallel solver is used instead of Brent.
    #[arg(long, default_value_t = 0usize)]
    walkers: usize,

    /// Distinguished-point threshold: number of low-order zero bits required
    /// in the x-coordinate.  Only used when `--walkers > 0` (default: 10).
    #[arg(long, default_value_t = 10u32)]
    theta: u32,

    /// Enable the negation map (BKNS) optimisation.
    ///
    /// When true, `solve_dp_negmap` is used instead of `solve_dp`.  Requires
    /// `--walkers > 0`.  Expected to reduce wall time by ~√2 vs plain DP.
    #[arg(long, default_value_t = false)]
    negmap: bool,

    /// Batch size B for the batched-inversion solver (default: 1 = no batching).
    ///
    /// When > 1, `solve_dp_batch` is used instead of `solve_dp` or `solve_dp_negmap`.
    /// Requires `--walkers > 0`.  Typical values: 8–32.
    #[arg(long, default_value_t = 1usize)]
    batch_size: usize,

    /// Enable the GLV endomorphism optimisation.
    ///
    /// When true, `solve_dp_glv` is used.  Requires `--walkers > 0` and
    /// `--curve secp-toy` (the GLV constants are secp-toy-specific).
    /// Supersedes `--negmap` and `--batch-size` when set.
    #[arg(long, default_value_t = false)]
    glv: bool,

    /// Total walk steps the distinguished-point solvers may take across all walkers.
    ///
    /// Only used when `--walkers > 0`.  Default: `64·√n` plus a start-up allowance of
    /// `64·walkers·batch·2^theta`.  Reaching it ends the run as budget exhaustion, which
    /// proves nothing about the answer.
    #[arg(long)]
    max_steps: Option<u64>,
}

/// Parse a `"x,y"` string into two `u64` values.
fn parse_point(s: &str) -> Result<(u64, u64), String> {
    let parts: Vec<&str> = s.splitn(2, ',').collect();
    if parts.len() != 2 {
        return Err(format!("expected 'x,y', got: {s}"));
    }
    let x = parts[0].trim().parse::<u64>()
        .map_err(|e| format!("bad x in '{s}': {e}"))?;
    let y = parts[1].trim().parse::<u64>()
        .map_err(|e| format!("bad y in '{s}': {e}"))?;
    Ok((x, y))
}

fn main() {
    let args = Args::parse();

    // Select curve and group order.
    let (curve, n) = match args.curve.as_str() {
        "secp-toy" => (secp_k1_toy(), SECP_N),
        // The stored generator has prime order `generic::N`; supplied points are not projected
        // onto its subgroup, so the solver's input check rejects points outside it.
        "generic" => (generic_curve(), GENERIC_N),
        other => {
            eprintln!("rho-dlog: unknown curve '{other}'; use 'secp-toy' or 'generic'");
            std::process::exit(1);
        }
    };

    // Parse base point P (or use generator).
    let g: AffinePoint<FpMonty> = match &args.p {
        None => curve.generator(),
        Some(s) => {
            let (x, y) = parse_point(s).unwrap_or_else(|e| {
                eprintln!("rho-dlog: --p parse error: {e}");
                std::process::exit(1);
            });
            AffinePoint::new(
                FpMonty::from_uint(Uint::<4>::from(x), &curve.p),
                FpMonty::from_uint(Uint::<4>::from(y), &curve.p),
            )
        }
    };

    // Parse target point Q.
    let (qx, qy) = parse_point(&args.q).unwrap_or_else(|e| {
        eprintln!("rho-dlog: --q parse error: {e}");
        std::process::exit(1);
    });
    let q: AffinePoint<FpMonty> = AffinePoint::new(
        FpMonty::from_uint(Uint::<4>::from(qx), &curve.p),
        FpMonty::from_uint(Uint::<4>::from(qy), &curve.p),
    );

    // Sanity checks.
    if !curve.is_on_curve(&g) {
        eprintln!("rho-dlog: base point P is not on the curve");
        std::process::exit(1);
    }
    if !curve.is_on_curve(&q) {
        eprintln!("rho-dlog: target point Q is not on the curve");
        std::process::exit(1);
    }

    // Solve: use parallel DP solver when --walkers > 0, otherwise Brent.
    // Priority within the parallel path (highest to lowest):
    //   --glv          → solve_dp_glv  (GLV endomorphism; secp-toy only)
    //   --batch-size>1 → solve_dp_batch (batched inversion)
    //   --negmap       → solve_dp_negmap (negation map)
    //   (default)      → solve_dp (distinguished-point search)
    // Every solver verifies `k·G == Q` itself, so there is no re-check here.
    // The step budget for a given number of walks per thread.
    let max_steps = |batch: usize| {
        args.max_steps
            .unwrap_or_else(|| default_max_steps(n, args.walkers, batch, args.theta))
    };
    let (walkers, theta, seed) = (args.walkers, args.theta, args.seed);
    let result = if args.walkers == 0 {
        solve_brent(&curve, &g, &q, n, seed, args.retries)
    } else if args.glv {
        // The solver reports `Unsupported` itself when the curve is not the GLV curve.
        let batch = if args.batch_size > 1 { args.batch_size } else { 16 };
        solve_dp_glv(&curve, &g, &q, n, walkers, batch, theta, seed, max_steps(batch))
    } else if args.batch_size > 1 {
        let batch = args.batch_size;
        solve_dp_batch(&curve, &g, &q, n, walkers, batch, theta, seed, max_steps(batch))
    } else if args.negmap {
        solve_dp_negmap(&curve, &g, &q, n, walkers, theta, seed, max_steps(1))
    } else {
        solve_dp(&curve, &g, &q, n, walkers, theta, seed, max_steps(1))
    };

    match result {
        Ok(solution) => {
            println!("k = {}", solution.k);
            println!("verified: k·G = Q  ✓");
        }
        Err(e) => {
            eprintln!("rho-dlog: {}", describe_error(&e));
            std::process::exit(1);
        }
    }
}

/// Default total walk-step budget of the distinguished-point solvers.
///
/// A collision takes about `1.25·√n` steps on average, and the chance of needing `c` times that
/// falls off like `exp(−c²/2)`; `64·√n` is far past any realistic run. The second term covers
/// the start-up cost: every walk (`walkers × batch` of them) needs about `2^theta` steps before
/// it can emit its first distinguished point.
fn default_max_steps(n: u64, walkers: usize, batch: usize, theta: u32) -> u64 {
    let collision = n.isqrt().saturating_add(1).saturating_mul(64);
    let walks = (walkers as u64).saturating_mul(batch as u64);
    let startup = walks.saturating_mul(1u64 << theta.min(40)).saturating_mul(64);
    collision.saturating_add(startup)
}

/// One line describing a solver failure, distinct for every error class.
fn describe_error(e: &DlogError) -> String {
    match e {
        DlogError::InvalidInput(defect) => {
            let why = match defect {
                InputDefect::GeneratorAtInfinity => "base point P is the point at infinity",
                InputDefect::GeneratorNotOnCurve => "base point P is not on the curve",
                InputDefect::TargetNotOnCurve => "target point Q is not on the curve",
                InputDefect::ZeroOrder => "group order is zero",
                InputDefect::OrderNotPrime => "group order is not prime",
                InputDefect::WrongGeneratorOrder => "n·P is not the point at infinity",
                InputDefect::TargetOutsideSubgroup => {
                    "n·Q is not the point at infinity (Q is outside the subgroup of P)"
                }
            };
            format!("invalid input: {why}")
        }
        DlogError::Unsupported(what) => format!("unsupported: {what}"),
        DlogError::BudgetExhausted { attempts, steps } => format!(
            "budget exhausted after {attempts} attempts and {steps} walk steps \
             (no answer found; this does not show that none exists)"
        ),
        DlogError::Inconsistent { k } => {
            format!("inconsistent: collision gave k = {k} but k·P ≠ Q (solver invariant failure)")
        }
        DlogError::InvariantFailure(what) => format!("solver invariant failure: {what}"),
    }
}
